7 // 06:00 - 07:00 PM\n  SLOT_07_08 // 07:00 - 08:00 PM\n  CUSTOM\n}\n\nenum PainSide {\n  RIGHT\n  LEFT\n  BOTH\n}\n\nenum PainType {\n  SHARP\n  DULL\n  BURNING\n  RADIATING\n}\n\nenum RomStatus {\n  NORMAL\n  RESTRICTED\n}\n\nenum PackageStatus {\n  ACTIVE\n  COMPLETED\n  EXPIRED\n  CANCELLED\n}\n\nenum PunctualityStatus {\n  ON_TIME\n  MODERATE_LATE\n  SEVERE_LATE\n}\n\n// --------------------------------------------------------\n// USER & AUTHENTICATION\n// --------------------------------------------------------\n\nmodel User {\n  id       String @id @default(cuid())\n  name     String\n  role     Role\n  password String\n\n  // Relations\n  sessions           Session[]\n  auditLogs          AuditLog[]\n  registeredPatients Patient[]            @relation("PatientRegistrar")\n  doctorSerials      Serial[]             @relation("DoctorSerials")\n  handlerSerials     Serial[]             @relation("HandlerSerials")\n  createdSerials     Serial[]             @relation("CreatedSerials")\n  doctorAssessments  ClinicalAssessment[] @relation("DoctorAssessments")\n  conductedSessions  TreatmentSession[]   @relation("HandlerSessions")\n  cashierBillings    BillingRecord[]      @relation("CashierBillings")\n  auditedBillings    BillingRecord[]      @relation("AuditedBillings")\n\n  // Room Relations\n  doctorRooms  Room[] @relation("RoomCurrentDoctor")\n  handlerRooms Room[] @relation("RoomCurrentHandler")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Session {\n  id    String @id @default(cuid())\n  token String @unique\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  ipAddress String?\n  userAgent String?\n  device    String?\n  browser   String?\n  os        String?\n\n  expiresAt    DateTime\n  revokedAt    DateTime?\n  lastAccessAt DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n}\n\nmodel AuditLog {\n  id     String      @id @default(cuid())\n  action AuditAction\n  status AuditStatus @default(SUCCESS)\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  entity    String?\n  entityId  String?\n  details   String?\n  ipAddress String?\n  userAgent String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n}\n\n// --------------------------------------------------------\n// PATIENT MASTER MODEL\n// --------------------------------------------------------\n\nmodel Patient {\n  id          String      @id @default(cuid())\n  patientId   String      @unique // e.g. "1800", "1806", "HPC-1800" (4-digit ID prominently used on physical cards)\n  nationalId  String? // NID / Passport / Identification\n  name        String // Bengali / English name (e.g. উম্মে হাবিবা, আব্দুল খালেক)\n  phone       String // Full phone (e.g. 01973-818213)\n  email       String?\n  dateOfBirth DateTime?\n  age         Int? // Recorded directly e.g. 22\n  gender      Gender      @default(MALE) // Crucial for male/female room and therapy segregation\n  bloodGroup  BloodGroup?\n  occupation  String?\n  address     String? // Location e.g. মোস্তফাপুর, সুইটি, ঝিনাইদহ, নড়াইল\n  city        String?\n\n  // Emergency Contact Details\n  emergencyContactName     String?\n  emergencyContactPhone    String?\n  emergencyContactRelation String?\n\n  // Medical Profile & Baseline Notes\n  primaryCondition   String? // Primary diagnosis / complaint (e.g. Lumbar Spondylosis)\n  allergies          String?\n  medicalHistory     String? // Past surgeries, hypertension, diabetes\n  currentMedications String?\n  notes              String? // General front-desk or doctor remarks\n\n  isActive Boolean @default(true)\n\n  registeredById String?\n  registeredBy   User?   @relation("PatientRegistrar", fields: [registeredById], references: [id], onDelete: SetNull)\n\n  // Relations\n  serials           Serial[]\n  assessments       ClinicalAssessment[]\n  treatmentSessions TreatmentSession[]\n  packages          PatientPackage[]\n  billingRecords    BillingRecord[]\n  occupiedRooms     Room[]               @relation("RoomCurrentPatient")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([phone])\n  @@index([name])\n  @@index([patientId])\n  @@index([gender])\n  @@index([registeredById])\n  @@index([createdAt])\n}\n\n// --------------------------------------------------------\n// SERIAL / QUEUE TOKEN (Daily Desk & Hourly Slot Register)\n// --------------------------------------------------------\n\nmodel Serial {\n  id           String  @id @default(cuid())\n  serialNumber Int // Daily sequential token (1, 2, 3... 50) per date\n  serialCode   String? @unique // Human code e.g. "APT-301" or "SER-20260826-01"\n\n  date       DateTime // Appointment / Queue date\n  timeSlot   String? // Display time e.g. "01:00 - 02:00 PM" or "1.00"\n  hourlySlot HourlySlot @default(CUSTOM) // Hourly bucket (10-11, 1-2, etc.)\n  gender     Gender     @default(MALE) // Gender track for chamber & bay allocation\n\n  status   SerialStatus @default(PENDING)\n  type     VisitType    @default(NEW_CONSULTATION)\n  priority Priority     @default(REGULAR)\n\n  // Logistics & Room Timing (Matching Care Handler Timing Log)\n  roomNo                String? // Room / Bay (e.g. "Chamber 1", "Rehab Studio 2", "Physio Bay 4")\n  toldTime              DateTime? // Promised arrival time told by receptionist on phone\n  scheduledTime         DateTime? // SD Time (Scheduled Desired Time)\n  inTime                DateTime? // In Time (Actual patient physical arrival/check-in)\n  latenessMinutes       Int               @default(0) // Lateness in minutes from toldTime\n  punctualityStatus     PunctualityStatus @default(ON_TIME) // ON_TIME, MODERATE_LATE, SEVERE_LATE\n  queuePriorityScore    Int               @default(0) // 0 for on-time/normal, +5 penalty offset if >30m late\n  therapyStartTime      DateTime? // T Time (Therapy execution start)\n  outTime               DateTime? // O Time (Completion / Departure)\n  restTime              DateTime? // R Time (Post-therapy recovery)\n  assignedTreatmentPlan String? // Doctor\'s prescribed modalities when routing to Handler\n\n  // Desk Flags\n  isReport Boolean @default(false) // e.g. "রবিন - রিপোর্ট"\n  notes    String? // Desk note / location remark (e.g. "মোস্তফাপুর")\n\n  // Day Cash Ledger Entry\n  fee              Float          @default(0.0)\n  paidAmount       Float          @default(0.0)\n  isPackageCovered Boolean        @default(false) // Marked as N.P (No Payment / Package covered)\n  paymentStatus    PaymentStatus  @default(UNPAID)\n  paymentMethod    PaymentMethod?\n\n  // Relations\n  patientId String\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  doctorId String?\n  doctor   User?   @relation("DoctorSerials", fields: [doctorId], references: [id], onDelete: SetNull)\n\n  handlerId String?\n  handler   User?   @relation("HandlerSerials", fields: [handlerId], references: [id], onDelete: SetNull)\n\n  createdById String?\n  createdBy   User?   @relation("CreatedSerials", fields: [createdById], references: [id], onDelete: SetNull)\n\n  billingRecords BillingRecord[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([date, serialNumber])\n  @@index([patientId])\n  @@index([doctorId])\n  @@index([handlerId])\n  @@index([date])\n  @@index([hourlySlot])\n  @@index([status])\n  @@index([gender])\n  @@index([createdAt])\n}\n\n// --------------------------------------------------------\n// CLINICAL PHYSIOTHERAPY ASSESSMENT (From HPC Assessment Form)\n// --------------------------------------------------------\n\nmodel ClinicalAssessment {\n  id   String   @id @default(cuid())\n  date DateTime @default(now())\n\n  // Patient Link\n  patientId String\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  doctorId String?\n  doctor   User?   @relation("DoctorAssessments", fields: [doctorId], references: [id], onDelete: SetNull)\n\n  // ## 2 Pain Details\n  painArea String? // e.g. "Neck", "Shoulder", "Back", "Knee", "Heel", "Others"\n  side     PainSide? @default(BOTH) // Right, Left, Both\n  duration String? // Duration of symptoms\n  painType PainType? @default(DULL) // Sharp, Dull, Burning, Radiating\n\n  // ## 3 Pain Scale (VAS 0-10)\n  vasScore          Int? // Baseline VAS score (0 to 10)\n  painIncreasesWith String? // "Movement", "Sitting", "Standing", "Walking"\n  painReducesWith   String? // "Rest", "Medicine", "Heat"\n\n  // ## 4 History\n  hasInjury          Boolean @default(false) // Injury / Accident\n  hasSurgery         Boolean @default(false) // Surgery History\n  postureAdviceGiven Boolean @default(false) // Posture advice given\n  previousTreatment  String? // "Medicine", "Physiotherapy"\n\n  // ## 5 Functional Limitation / Difficulty In\n  difficultyIn String? // "Bending", "Sitting", "Standing", "Walking", "Lifting"\n\n  // ## 6 Physical Examination\n  rom            RomStatus @default(NORMAL) // Normal / Restricted\n  hasMuscleSpasm Boolean   @default(false)\n  hasTenderness  Boolean   @default(false)\n  hasSwelling    Boolean   @default(false)\n\n  // ## 7 Physiotherapy Diagnosis\n  diagnosis String?\n\n  // ## 8 Treatment Plan (Prescribed Modalities)\n  prescribedModalities String? // "Hot pack", "IFT/TENS", "Ultrasound (UST)", "SWD", "PMF", "Stretching", "Strengthening", "Posture correction"\n\n  // ## 9 Home Advice & Follow-up\n  exerciseExplained Boolean @default(true)\n  homePostureAdvice Boolean @default(true)\n  postTreatmentVas  Int? // VAS Pain score after treatment (0-10)\n  improvement       String? // Improvement assessment note\n  clinicalNotes     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([patientId])\n  @@index([doctorId])\n  @@index([date])\n}\n\n// --------------------------------------------------------\n// MULTI-SESSION TREATMENT LOG (From HPC Clinical Session Sheet)\n// --------------------------------------------------------\n\nmodel TreatmentSession {\n  id            String   @id @default(cuid())\n  date          DateTime @default(now())\n  sessionNumber Int? // Session / Day sequence (e.g. Day 1, Day 2...)\n\n  // Patient Link\n  patientId String\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n\n  // Assigned Care Handler / Therapist\n  handlerId String?\n  handler   User?   @relation("HandlerSessions", fields: [handlerId], references: [id], onDelete: SetNull)\n\n  // Clinical Vitals & Modalities Delivered\n  bloodPressure      String? // BP (e.g. "120/80")\n  complaint          String? // Patient\'s complaint that day\n  treatmentPlan      String? // Plan for the day (e.g. "IFT (20), UST (10), SWD (20)")\n  treatmentPerformed String // Modalities executed (e.g. "D-N, UST, SWD, T-40, TENS, IFT, mass, PMF, Nemas, Lazas")\n  notes              String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([patientId])\n  @@index([handlerId])\n  @@index([date])\n}\n\n// --------------------------------------------------------\n// PATIENT REHABILITATION PACKAGE (From HPC Package Ledger)\n// --------------------------------------------------------\n\nmodel PatientPackage {\n  id          String        @id @default(cuid())\n  packageName String // e.g. "21-30 Days Pain Care Rehabilitation Package"\n  totalDays   Int           @default(30) // 21 - 30 days\n  totalAmount Float // Package price (e.g. 10000, 13000, 20000)\n  paidAmount  Float         @default(0.0)\n  dueAmount   Float         @default(0.0)\n  startDate   DateTime      @default(now())\n  endDate     DateTime?\n  status      PackageStatus @default(ACTIVE)\n  notes       String?\n\n  // Relations\n  patientId      String\n  patient        Patient         @relation(fields: [patientId], references: